-- PCA/FCM pilot positions. These are visualization coordinates, not clinical distances.
-- Matched source dataset: data/pilot_3d_positions.json
-- Requires migrations 017 and 018; no patient events affected.
on conflict(disease_id) do update set
 x=excluded.x,y=excluded.y,z=excluded.z,
 group_label=excluded.group_label,
 fuzzy_cluster=excluded.fuzzy_cluster,
 membership_strength=excluded.membership_strength,
 coverage_kind=excluded.coverage_kind,
 model_version=excluded.model_version;
